import { adminCreateUser, adminDeleteUser } from "../../lib/adminApi";
import { supabase } from "../../lib/supabaseClient";
import { VendorFormValues } from "../../types/schema/vendor.schema";

// =====================================================================
// PHASE 8 — party_type and the single source of truth for roles
// =====================================================================
// Two changes, matching setEmployeeService.ts:
//
//   1. partyType is sent in user_metadata so handle_new_user() can set
//      users.party_type. Phase 1 made that column NOT NULL with no
//      default, so without this the insert fails outright — see
//      phase8-create-employee.sql. The trigger can also derive it from
//      the role, but stating it here means this flow does not depend on
//      the Vendor role keeping its name.
//
//   2. The user_roles write is idempotent. It is the source of truth
//      (phase2-resolver.sql DECISION 7) and this flow already wrote it;
//      the upsert is so it keeps working once the trigger writes it too.
//
// users.role_id needs no reconciling here: one roleId constant feeds
// both the metadata and the user_roles row, so they cannot disagree.
// =====================================================================

export async function addVendor(form: VendorFormValues) {
  const email = (form.email ?? "").trim();
  const password = form.password ?? "";
  const shouldCreateAuthUser = email.length > 0 && password.length > 0;

  const roleId = "7cfabb14-ee17-48bc-b03f-4199ef32d1e0";

  // 1) Create auth user only if email + password exist
  let authUserId: string | null = null;

  if (shouldCreateAuthUser) {
    const { data: userData, error: userError } =
      await adminCreateUser("vendor", {
      email: email,
      password,
      userMetadata: {
          firstName: form.vendor_name,
          lastName: (form.contact_name ?? "").trim() || null,
          phone: (form.phone_number ?? "").trim() || null,
          roleId,
          partyType: "vendor",
        },
    });

    if (userError) {
      console.error("Error creating auth user:", userError);
      return {
        success: false,
        error: userError,
        message: "فشل في إنشاء المستخدم",
      };
    }

    authUserId = userData.user?.id ?? null;
    if (!authUserId) {
      return {
        success: false,
        error: new Error("No user id returned from auth.createUser"),
        message: "فشل في إنشاء المستخدم - معرف المستخدم غير متاح",
      };
    }
  }

  // 2) Resolve bank name if a bank was selected
  const bankId = (form.bank_id ?? "").trim();
  let bankName: string | null = null;

  if (bankId) {
    const { data: bank, error: bankErr } = await supabase
      .schema("lookups")
      .from("banks")
      .select("name")
      .eq("id", bankId)
      .single();

    if (bankErr) {
      console.error("Error fetching bank:", bankErr);
      return {
        success: false,
        error: bankErr,
        message: "فشل في جلب بيانات البنك",
      };
    }

    bankName = bank?.name ?? null;
  }

  // 3) Insert vendor row (id generated by table), link user_id if exists
  const { data: vendorRow, error: vendorErr } = await supabase
    .from("vendors")
    .insert({
      vendor_name: form.vendor_name,
      contact_name: (form.contact_name ?? "").trim() || null,
      email: email || null,
      phone_number: (form.phone_number ?? "").trim() || null,
      alt_phone_number: (form.alt_phone_number ?? "").trim() || null,
      country: (form.country ?? "").trim() || null,
      city: (form.city ?? "").trim() || null,
      address: (form.address ?? "").trim() || null,
      whatsapp_number: (form.whatsapp_number ?? "").trim() || null,
      user_id: authUserId,
      bank_id: bankId || null,
      bank_name: bankName,
      bank_number: (form.bank_number ?? "").trim() || null,
      bank_holder_name: (form.bank_holder_name ?? "").trim() || null,
    })
    .select("id,user_id")
    .single();

  if (vendorErr) {
    console.error("Error inserting vendor:", vendorErr);
    return {
      success: false,
      error: vendorErr,
      message: "فشل في إنشاء البائع",
    };
  }

  // Link speciality to vendor if provided
  if (form.specialization_id) {
    const { error: specError } = await supabase
      .from("vendor_specialities")
      .insert({
        vendor_id: vendorRow.id,
        speciality_id: form.specialization_id,
      });

    if (specError) {
      console.warn("Warning inserting vendor speciality:", specError);
    }
  }

  // 4) role only if auth user exists
  if (authUserId) {
    const { error: userRoleError } = await supabase
      .from("user_roles")
      .upsert(
        { role_id: roleId, user_id: authUserId },
        { onConflict: "user_id,role_id", ignoreDuplicates: true },
      );

    if (userRoleError) {
      console.error("Error inserting user role data:", userRoleError);
      return {
        success: false,
        error: userRoleError,
        message: "فشل في تعيين دور المستخدم",
      };
    }
  }

  return {
    success: true,
    message: authUserId
      ? "تم إنشاء البائع (مع حساب دخول) بنجاح"
      : "تم إنشاء البائع بنجاح (بدون حساب دخول)",
    vendorId: vendorRow.id,
    authUserId,
  };
}

export async function AssignUserToVendor({
  vendorId,
  email,
  password,
}: {
  vendorId: string;
  email: string;
  password: string;
}) {
  const roleId = "7cfabb14-ee17-48bc-b03f-4199ef32d1e0"; // Vendor role

  // 1) Fetch the vendor to get their info for auth metadata
  const { data: vendor, error: fetchErr } = await supabase
    .from("vendors")
    .select("id, vendor_name, contact_name, phone_number")
    .eq("id", vendorId)
    .single();

  if (fetchErr || !vendor) {
    return {
      success: false,
      error: fetchErr,
      message: "فشل في جلب بيانات المورد",
    };
  }

  // 2) Create the auth user
  const { data: userData, error: userError } =
    await adminCreateUser("vendor", {
      email: email.trim(),
      password,
      userMetadata: {
        firstName: vendor.vendor_name,
        lastName: vendor.contact_name ?? null,
        phone: vendor.phone_number ?? null,
        roleId,
        partyType: "vendor",
      },
    });

  if (userError || !userData.user) {
    return {
      success: false,
      error: userError,
      message: "فشل في إنشاء حساب المستخدم",
    };
  }

  const authUserId = userData.user.id;

  // 3) Link the auth user to the vendor row
  const { error: updateErr } = await supabase
    .from("vendors")
    .update({ user_id: authUserId, email: email })
    .eq("id", vendorId);

  if (updateErr) {
    // Rollback: delete the orphaned auth user
    await adminDeleteUser(authUserId);
    return {
      success: false,
      error: updateErr,
      message: "فشل في ربط الحساب بالمورد",
    };
  }

  // 4) Assign the vendor role
  const { error: roleErr } = await supabase
    .from("user_roles")
    .upsert(
      { role_id: roleId, user_id: authUserId },
      { onConflict: "user_id,role_id", ignoreDuplicates: true },
    );

  if (roleErr) {
    return {
      success: false,
      error: roleErr,
      message: "فشل في تعيين دور المستخدم",
    };
  }

  return {
    success: true,
    message: "تم ربط الحساب بالمورد بنجاح",
    authUserId,
    vendorId,
  };
}
